import pandas as pd

def users_percentage(users: pd.DataFrame, register: pd.DataFrame) -> pd.DataFrame:
    total_users = len(users)
    if total_users == 0 or register.empty:
        return pd.DataFrame({'contest_id': [], 'percentage': []})
    grouped = register.groupby('contest_id')['user_id'].count().reset_index()
    grouped['percentage'] = (grouped['user_id'] * 100.0 / total_users).round(2)
    res = grouped.sort_values(by=['percentage', 'contest_id'], ascending=[False, True])
    return res[['contest_id', 'percentage']]
